export type BeginnerGuide = {
  slug: string;
  title: string;
  group: "Getting started" | "Choosing for your life" | "Buying with confidence" | "Everyday wear" | "Your signature scent" | "Discovery sets" | "Small bottles" | "Selection quizzes" | "Starter kits" | "Understanding perfume" | "Scent notes" | "Exploring a note" | "Note-led samples" | "Choosing a note" | "Formats and concentration" | "Application guides" | "Wear-time guides" | "First formats" | "Everyday formats" | "Hot-weather choices" | "Sample formats" | "Storage guides" | "Application amounts" | "Performance basics" | "Wear-time comparisons" | "Projection comparisons" | "Understanding fading" | "Day-long trials" | "Fabric comparisons" | "Wear routines" | "Noticeability" | "Scent fit" | "Occasions and etiquette" | "Occasion shortlists" | "Subtle occasions" | "Fresh occasions" | "Woody occasions" | "Unisex occasions" | "Occasion sample sets" | "Choosing by occasion" | "Occasion budgets" | "Weather and perfume" | "Weather shortlists" | "Fresh weather choices" | "Woody weather choices" | "Light weather choices" | "Weather longevity" | "Weather sample trials" | "Weather selection" | "Sweet weather choices" | "Perfume value" | "Bottle budgets" | "Sample-set budgets" | "Gift-set budgets" | "Longevity budgets" | "Daily-wear budgets" | "Unisex budgets" | "First-purchase budgets" | "Discovery-kit budgets" | "Samples and testers" | "Buying sample formats" | "Choosing sample formats" | "Sample-format value" | "First sample purchases" | "Ordering sample formats" | "Comparing sample prices" | "Preference-led samples" | "From samples to bottles" | "Product identity and trust" | "Checking sellers" | "Seller reliability" | "Questions before purchase" | "Comparing seller reviews" | "Reading return terms" | "Clarifying authenticity" | "Purchase warning signs" | "Comparing seller prices" | "Application and care" | "Storing fragrance formats" | "Travelling with fragrance" | "Using fragrance formats" | "Planning fragrance quantity" | "Labelling fragrance formats" | "Container care" | "Organizing fragrance formats" | "Packing fragrance formats";
  answer: string;
  sections: { title: string; body: string }[];
  exercise: string;
  humeTip: string;
  nextStep: "quiz" | "samples" | "shop";
  productIds: string[];
  requiredNote?: string;
  chart?: { headers: string[]; rows: string[][] };
  sources?: { title: string; url: string }[];
};

function guide(title: string, group: BeginnerGuide["group"], answer: string, sections: [string, string][], exercise: string, humeTip: string, nextStep: BeginnerGuide["nextStep"] = "samples", productIds: string[] = []): BeginnerGuide {
  return { title, group, slug: title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""), answer, sections: sections.map(([title, body]) => ({ title, body })), exercise, humeTip, nextStep, productIds };
}

