export const BEGINNER_GUIDES_PATH = "/perfume-beginners";
export function beginnerGuidePath(slug: string) { return `${BEGINNER_GUIDES_PATH}/${slug}`; }
export function getBeginnerGuide(slug: string) { return BEGINNER_PERFUME_GUIDES.find(guide => guide.slug === slug); }
